# Assuming the incorrect hypothesis that a solution exists if and only if m is divisible by 3.
count = 0
for m in range(1, 101):
    if m % 3 == 0:
        count += 1
print(count)

def solve_final():
    count = 0
    for m in range(1, 101):
        S = m * (m + 1) // 2
        if S % 3 != 0:
            continue
        K = S // 3

        dp = [0] * (K + 1)
        dp[0] = 1

        for i in range(1, m + 1):
            new_dp = [0] * (K + 1)
            for s1 in range(K + 1):
                # Case 1: i in neither
                new_dp[s1] |= dp[s1]
                # Case 2: i in X
                if s1 >= i:
                    new_dp[s1] |= dp[s1-i]
                # Case 3: i in Y
                new_dp[s1] |= (dp[s1] << i)

            mask = (1 << (K + 1)) - 1
            for s1 in range(K + 1):
                dp[s1] = new_dp[s1] & mask

            if (dp[K] & (1 << K)):
                count += 1
                print(f"m={m}, K={K}, found=True")
                break
        else:
            print(f"m={m}, K={K}, found=False")
    return count

print(solve_final())

